package io.github.ningpp.compat;

import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.MapperFeature;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.PropertyNamingStrategies;
import com.fasterxml.jackson.databind.SerializationFeature;

/** Replacement for System.Text.Json.JsonSerializer (generated by CSharpToJava converter). */
public class JsonSerializer {
    private static final ObjectMapper MAPPER = new ObjectMapper()
        .configure(SerializationFeature.FAIL_ON_EMPTY_BEANS, false)
        .configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, false);

    private static ObjectMapper mapperFor(Object options) {
        if (options instanceof JsonSerializerOptions opts) {
            ObjectMapper mapper = new ObjectMapper()
                .configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, false);
            if (opts.isWriteIndented()) {
                mapper.enable(SerializationFeature.INDENT_OUTPUT);
            }
            if (opts.isPropertyNameCaseInsensitive()) {
                mapper.enable(MapperFeature.ACCEPT_CASE_INSENSITIVE_PROPERTIES);
                mapper.enable(MapperFeature.ACCEPT_CASE_INSENSITIVE_ENUMS);
            }
            String policy = opts.getPropertyNamingPolicy();
            if (policy != null) {
                switch (policy) {
                    case JsonNamingPolicy.SnakeCaseLower:
                    case JsonNamingPolicy.SnakeCaseUpper:
                        mapper.setPropertyNamingStrategy(PropertyNamingStrategies.SNAKE_CASE);
                        break;
                    case JsonNamingPolicy.KebabCaseLower:
                    case JsonNamingPolicy.KebabCaseUpper:
                        mapper.setPropertyNamingStrategy(PropertyNamingStrategies.KEBAB_CASE);
                        break;
                    case JsonNamingPolicy.CamelCase:
                    default:
                        mapper.setPropertyNamingStrategy(PropertyNamingStrategies.LOWER_CAMEL_CASE);
                        break;
                }
            }
            return mapper;
        }
        return MAPPER;
    }

    @SuppressWarnings("unchecked")
    public static <T> String serialize(T value, Object options) {
        try { return mapperFor(options).writeValueAsString(value); }
        catch (Exception e) { throw new RuntimeException(e); }
    }

    @SuppressWarnings("unchecked")
    public static <T> String serialize(T value) {
        try { return MAPPER.writeValueAsString(value); }
        catch (Exception e) { throw new RuntimeException(e); }
    }

    @SuppressWarnings("unchecked")
    public static <T> T deserialize(String json, Class<T> clazz) {
        try { return MAPPER.readValue(json, clazz); }
        catch (Exception e) { throw new RuntimeException(e); }
    }

    /** Overload matching the converter-emitted call shape deserialize(T.class, json). */
    @SuppressWarnings("unchecked")
    public static <T> T deserialize(Class<T> clazz, String json) {
        try { return MAPPER.readValue(json, clazz); }
        catch (Exception e) { throw new RuntimeException(e); }
    }

    /**
     * Overload for generic targets (e.g. List<SciPyResult>): the converter emits
     * deserialize(new TypeReference<CSharpList<SciPyResult>>() {}, json) so Jackson
     * deserializes elements with their concrete type instead of LinkedHashMap.
     */
    @SuppressWarnings("unchecked")
    public static <T> T deserialize(com.fasterxml.jackson.core.type.TypeReference<T> typeRef, String json) {
        try { return MAPPER.readValue(json, typeRef); }
        catch (Exception e) { throw new RuntimeException(e); }
    }

    /** Overload for C# Deserialize&lt;T&gt;(json, JsonSerializerOptions): applies naming policy. */
    @SuppressWarnings("unchecked")
    public static <T> T deserialize(Class<T> clazz, String json, Object options) {
        try { return mapperFor(options).readValue(json, clazz); }
        catch (Exception e) { throw new RuntimeException(e); }
    }

    /** Overload for C# Deserialize&lt;T&gt;(json, JsonSerializerOptions) with a generic target. */
    @SuppressWarnings("unchecked")
    public static <T> T deserialize(com.fasterxml.jackson.core.type.TypeReference<T> typeRef, String json, Object options) {
        try { return mapperFor(options).readValue(json, typeRef); }
        catch (Exception e) { throw new RuntimeException(e); }
    }

    public static Object deserialize(String json) {
        try { return MAPPER.readValue(json, Object.class); }
        catch (Exception e) { throw new RuntimeException(e); }
    }

    @SuppressWarnings("unchecked")
    public static <T> T deserialize(byte[] json, Class<T> clazz) {
        try { return MAPPER.readValue(json, clazz); }
        catch (Exception e) { throw new RuntimeException(e); }
    }

    public static Object deserialize(byte[] json) {
        try { return MAPPER.readValue(json, Object.class); }
        catch (Exception e) { throw new RuntimeException(e); }
    }

    /** Overload for C# Deserialize&lt;T&gt;(ref Utf8JsonReader) call sites: the reader is a
     * converter-generated Utf8JsonReader whose underlying span is extracted reflectively. */
    @SuppressWarnings("unchecked")
    public static <T> T deserialize(Class<T> clazz, Object reader) {
        try {
            Object span = reader.getClass().getMethod("getOriginalSpan").invoke(reader);
            Object arr = span.getClass().getMethod("toArray").invoke(span);
            byte[] bytes;
            if (arr instanceof byte[]) {
                bytes = (byte[]) arr;
            } else {
                Object[] objs = (Object[]) arr;
                bytes = new byte[objs.length];
                for (int i = 0; i < objs.length; i++) {
                    bytes[i] = ((Number) objs[i]).byteValue();
                }
            }
            return MAPPER.readValue(bytes, clazz);
        }
        catch (Exception e) {
            throw new RuntimeException(e);
        }
    }
}
